                pending.push(dep);
            }
        }
    }
    let mut order = Vec::new(); let mut visiting = BTreeSet::new(); let mut done = BTreeSet::new();
    for name in &selected { visit(name, &services, &selected, &mut visiting, &mut done, &mut order)?; }
