#[cfg(test)]
mod removal_tests {
    use super::*;

    fn stopped() -> Wanted {
        Wanted { pid: 0, start: [0; 12], paused: false, want: b'd', state: 0,
            down: true, linked: false, new_service: false }
    }
    #[test]
    fn only_dormant_service_and_logger_can_leave_the_overlay() {
        let main = stopped(); let logger = stopped();
        assert!(validate_dormant_removal(&main, Some(&logger)).is_ok());
        let mut without_marker = stopped(); without_marker.down = false;
        assert!(validate_dormant_removal(&without_marker, None).is_ok());
        let mutations: [fn(&mut Wanted); 6] = [
            |w: &mut Wanted| w.linked = true,
            |w: &mut Wanted| w.new_service = true,
            |w: &mut Wanted| w.paused = true,
            |w: &mut Wanted| w.pid = 42,
            |w: &mut Wanted| w.state = 1,
            |w: &mut Wanted| w.want = b'u',
        ];
        for change in mutations {
            let mut active = stopped(); change(&mut active);
            assert!(validate_dormant_removal(&active, Some(&logger)).is_err());
            assert!(validate_dormant_removal(&main, Some(&active)).is_err());
        }
    }
}

